from esm_for_browser import load_modules
# python tests/cm-editor-browser-regression.py — GLSL 편집기(CodeMirror 6): textarea 창구 · studio 연동 · 편집 기능 · GLSL 도우미 (GPU 불필요)
import os
from pathlib import Path
from playwright.sync_api import sync_playwright
root=Path(__file__).resolve().parent.parent
html=(root/'index.html').read_text();html=html[:html.index('    <!-- ES Modules:')]+'</body></html>'
with sync_playwright() as p:
    browser=p.chromium.launch(headless=True,executable_path=os.environ.get('CHROMIUM_PATH') or None,args=['--no-sandbox'])
    page=browser.new_page(viewport={'width':1440,'height':900});errors=[]
    page.on('pageerror',lambda err:errors.append(str(err)))
    page.set_content(html);page.add_style_tag(content=(root/'style.css').read_text())
    load_modules(page,root,['studio'])
    page.evaluate('''() => {
      const src="#version 300 es\\nprecision highp float;\\nout vec4 fragColor;\\nvoid main() {\\n    fragColor = vec4(1.0);\\n}\\n",state={image:src,passes:[],imageChannels:{}};
      const renderer={getUserUniforms:()=>[],getFragmentSource:()=>state.image,getPassDefinitions:()=>structuredClone(state.passes),getImageChannels:()=>structuredClone(state.imageChannels),
        getPasses:()=>state.passes.map(p=>({name:p.name})),getTextures:()=>[],getStats:()=>({running:false}),setPreviewPass:()=>{},
        validatePassConfiguration:()=>{},validateFragment:s=>{if(s.includes('SYNTAX'))throw new Error('Fragment Shader 컴파일 실패:\\nERROR: 0:5: test diagnostic');return true;},
        setFragment:s=>state.image=s,setPasses:(passes,channels)=>{state.passes=structuredClone(passes);state.imageChannels=structuredClone(channels);},
        setImageChannels:x=>state.imageChannels=structuredClone(x),setPassFragment:(name,s)=>state.passes.find(p=>p.name===name).fragment=s,
        setPassChannels:(name,channels)=>state.passes.find(p=>p.name===name).channels=structuredClone(channels),resetSimulation:()=>{}};
      renderer.applyProject=scene=>{
        for(const [name,source] of [["Image",scene.image],...scene.passes.map(p=>[p.name,p.fragment])]){try{renderer.validateFragment(source);}catch(error){error.passName=name;throw error;}}
        renderer.setPasses(scene.passes,scene.imageChannels);renderer.setFragment(scene.image);return true;};
      window.testRenderer=renderer;
      window.testStudio=TestStudio.mount(renderer,{fragment:src},null,{builtins:[{name:"smoothstep",sig:"T smoothstep(T e0, T e1, T x)",desc:"부드러운 계단"},{name:"mix",sig:"T mix(T a, T b, T t)",desc:"선형 보간"}],lookup:n=>({smoothstep:{sig:"T smoothstep(T e0, T e1, T x)",desc:"부드러운 계단"},mix:{sig:"T mix(T a, T b, T t)",desc:"선형 보간"}})[n]||null,notify:t=>window.lastNotice=t});
      testStudio.open();document.getElementById('studioLive').checked=false;
    }''')
    n=[0]
    def check(cond,label):
        assert cond,label;n[0]+=1;print('PASS',f'{n[0]:02d}',label,flush=True)
    def js(expr,arg=None):return page.evaluate(expr,arg)
    val=lambda:js("document.getElementById('studioCode').value")
    content=page.locator('.cm-content')
    def caret_to_end():content.click();page.keyboard.press('Control+End')
    def wait(ms=60):page.wait_for_timeout(ms)

    # ---- 장착 · 창구 ----
    check(js("!!document.querySelector('.studio-cm-host .cm-editor') && document.querySelector('.studio-editor-frame').classList.contains('is-codemirror')"),'CodeMirror view is mounted in the editor frame')
    check(js("document.getElementById('studioCode').hidden && !document.querySelector('#studioHighlight, #studioLines, #studioCompletion, #studioFindPanel')"),'the model textarea is hidden and no classic editor layers exist')
    check(val()==js("testStudio.getProject().image") and js("document.querySelector('.cm-content').textContent.includes('fragColor = vec4(1.0);')"),'facade value and CodeMirror document hold the project source')
    classes=js("[...new Set([...document.querySelectorAll('.cm-content [class*=glsl-]')].map(n=>n.className))].sort()")
    check({'glsl-directive','glsl-keyword','glsl-type','glsl-number'}<=set(classes),f'GLSL tokens use the shared .glsl-* colors: {classes}')
    js("document.getElementById('studioCode').setSelectionRange(10,4,'backward')")
    check(js("(t=>[t.selectionStart,t.selectionEnd,t.selectionDirection])(document.getElementById('studioCode'))")==[4,4,'none'],'setSelectionRange clamps an inverted range like a textarea')
    js("document.getElementById('studioCode').setSelectionRange(4,10,'backward')")
    check(js("(t=>[t.selectionStart,t.selectionEnd,t.selectionDirection])(document.getElementById('studioCode'))")==[4,10,'backward'],'backward selection round-trips through the facade')
    js("(t=>{t.setSelectionRange(0,0);t.setRangeText('AB',0,0,'end');})(document.getElementById('studioCode'))")
    check(val().startswith('AB#version') and js("document.getElementById('studioCode').selectionStart")==2,'setRangeText "end" mode inserts and moves the caret')
    js("(t=>{t.setSelectionRange(5,5);t.setRangeText('',0,2,'preserve');})(document.getElementById('studioCode'))")
    check(val().startswith('#version') and js("document.getElementById('studioCode').selectionStart")==3,'setRangeText "preserve" maps the selection after the edit')

    # ---- studio 연동: 입력 → 미적용, 되돌리기, 프로젝트 교체, 진단, 패스 전환 ----
    js("testStudio.apply()");wait()
    caret_to_end();page.keyboard.type('// typed');wait(120)
    check(val().endswith('// typed'),'typing in CodeMirror updates the facade value')
    check(js("!document.getElementById('studioUndo').disabled"),'studio receives the input event (Undo becomes available)')
    page.keyboard.press('Control+z');wait(120)
    check('// typed' not in val(),'Ctrl+Z goes to studio history and restores the document')
    page.keyboard.press('Control+y');wait(120)
    check(val().endswith('// typed'),'Ctrl+Y redoes through studio history')
    js("testStudio.setProject({image:'#version 300 es\\nprecision highp float;\\nout vec4 fragColor;\\nvoid main() {\\n    float v = 1.0;\\n    v = v * 2.0;\\n    fragColor = vec4(v);\\n}\\n',passes:[],imageChannels:{}})");wait()
    check(js("document.querySelector('.cm-content').textContent.includes('float v = 1.0;')"),'setProject replaces the CodeMirror document')
    caret_to_end();page.keyboard.type('SYNTAX');js("testStudio.apply()");wait(150)
    check(js("document.querySelectorAll('.cm-lint-marker').length")>=1,'compile diagnostics appear in the CodeMirror lint gutter')
    page.keyboard.press('Control+z');wait(80)
    js("testStudio.setProject({image:'#version 300 es\\nout vec4 fragColor;\\nvoid main(){ fragColor = vec4(1.0); }\\n',passes:[{name:'A',fragment:'#version 300 es\\nout vec4 fragColor;\\nvoid main(){ fragColor = vec4(0.5); } // buffer A\\n',format:'rgba8',scale:1,channels:{}}],imageChannels:{}})");wait()
    content.click();page.keyboard.press('Alt+PageDown');wait(120)
    check(js("document.querySelector('.studio-pass-tabs .is-active').textContent")=='Buffer A' and 'buffer A' in js("document.querySelector('.cm-content').textContent"),'Alt+PageDown reaches studio and switches the pass shown in CodeMirror')
    page.keyboard.press('Alt+PageUp');wait(120)

    # ---- 편집 기능 ----
    js("testStudio.setProject({image:'#version 300 es\\nprecision highp float;\\nout vec4 fragColor;\\nvoid main() {\\n    float v = 1.0;\\n    v = v * 2.0;\\n    fragColor = vec4(v);\\n}\\n',passes:[],imageChannels:{}})");wait()
    check(js("document.querySelectorAll('.cm-foldGutter span[title]').length")>=1,'brace blocks are foldable')
    js("(t=>{const at=t.value.indexOf('v = 1.0');t.setSelectionRange(at,at);})(document.getElementById('studioCode'))");content.focus()
    for _ in range(3):page.keyboard.press('Control+d')
    check('다중 선택 3개' in page.locator('#studioCursor').inner_text(),'Ctrl+D adds occurrences as real CodeMirror selections')
    page.keyboard.type('w');wait()
    check(len([m for m in val().split() if m.strip(';()*=') == 'w'])>=3,'typing edits every cursor')
    page.keyboard.press('ArrowLeft');wait()
    check('다중 선택 3개' in page.locator('#studioCursor').inner_text(),'arrow keys move all cursors together (multi-cursor kept)')
    page.keyboard.press('Escape');wait()
    check('다중' not in page.locator('#studioCursor').inner_text(),'Escape returns to a single cursor')
    caret_to_end();page.keyboard.type('\nvoid f() {');page.keyboard.press('Enter');page.keyboard.type('x;')
    check(val().rstrip().endswith('void f() {\n    x;\n}'),'Enter between auto-closed braces indents one level')
    js("(t=>{t.setRangeText('\\nif (a) {\\n    y;\\n    ',t.value.length,t.value.length,'end');})(document.getElementById('studioCode'))");content.focus();page.keyboard.press('Control+End');page.keyboard.type('}')
    check(val().endswith('if (a) {\n    y;\n}'),'typing } on an indented line dedents it')
    caret_to_end();page.keyboard.type('\nfloat q = smst');wait(400)
    labels=js("[...document.querySelectorAll('.cm-tooltip-autocomplete li .cm-completionLabel')].map(x=>x.textContent)")
    check(labels and labels[0]=='smoothstep',f'fuzzy completion ranks smoothstep first for "smst": {labels[:3]}')
    page.keyboard.press('Enter');wait()
    check(val().rstrip().endswith('float q = smoothstep'),'Enter accepts the completion')
    page.keyboard.type(';\nfloat t = uTim');wait(400);page.keyboard.press('Enter');wait()
    check('uniform float uTime;' in val() and val().index('uniform float uTime;')>val().index('precision highp float;'),'picking an undeclared app uniform also inserts its declaration after precision')
    page.keyboard.press('Control+f');wait()
    check(page.is_visible('.cm-search'),'Ctrl+F opens the search panel')
    check(js("document.activeElement?.name")=='search','Ctrl+F focuses the find field')
    page.keyboard.type('float');wait()
    total=js("document.querySelector('.studio-find-count').textContent")
    check(total.endswith('/'+str(val().count('float'))),f'find shows the match count: {total}')
    page.keyboard.press('Enter');wait();first=js("document.querySelector('.studio-find-count').textContent")
    check(first.startswith('1/'),f'Enter jumps to the first match: {first}')
    page.keyboard.press('Shift+Enter');wait()
    check(js("document.querySelector('.studio-find-count').textContent")!=first,'Shift+Enter goes to the previous match')
    # Ctrl+F = 찾기만: 바꾸기 줄은 숨기고, 찾기 모드에서는 바꾸기 단축키도 문서를 바꾸지 않는다
    check(js("document.querySelector('.studio-find').dataset.mode")=='find' and not page.is_visible('.studio-find [name=replace]') and not page.is_visible('.studio-find [name=replaceAll]'),'Ctrl+F shows only the find row (replace row hidden)')
    check(js("document.querySelector('.studio-find [name=mode]').getAttribute('aria-expanded')")=='false','the replace toggle reports collapsed in find mode')
    before=val();page.keyboard.press('Control+Alt+Enter');wait()
    check(val()==before,'Ctrl+Alt+Enter does not replace in find-only mode')
    page.keyboard.press('Tab')
    check(js("document.activeElement?.name")!='replace','Tab in find mode skips the hidden replace field')
    page.keyboard.press('Shift+Tab')
    # 창 안에서 Ctrl+H = 찾아 바꾸기로 바꾸고 바꿀 내용 칸에 초점
    page.keyboard.press('Control+h');wait()
    check(js("document.querySelector('.studio-find').dataset.mode")=='replace' and page.is_visible('.studio-find [name=replace]') and js("document.activeElement?.name")=='replace','Ctrl+H inside the panel opens the replace row and focuses it')
    page.keyboard.press('Shift+Tab')
    check(js("document.activeElement?.name")=='search','Shift+Tab from the replace field returns to the find field')
    page.keyboard.press('Tab')
    check(js("document.activeElement?.name")=='replace','Tab from the find field goes straight to the replace field')
    rows=js("(()=>{const r=n=>Math.round(document.querySelector('.studio-find '+n).getBoundingClientRect().top);return [r('[name=search]'),r('[name=next]'),r('[name=replace]'),r('[name=replaceAll]')]})()")
    check(rows[0]==rows[1] and rows[2]==rows[3] and rows[2]>rows[0],f'find tools sit on the find row and replace tools on the replace row: {rows}')
    # 닫기(×)와 모든 칸이 창 안에 있다: 넓은 편집기(한 줄)와 좁은 편집기(480px 이하 — 찾기 도구가 아래 줄로) 둘 다
    inside="(()=>{const p=document.querySelector('.studio-find').getBoundingClientRect();return [...document.querySelectorAll('.studio-find > *, .studio-find-tools > *')].filter(n=>n.offsetParent).every(n=>{const r=n.getBoundingClientRect();return r.left>=p.left-0.5&&r.right<=p.right+0.5;})})()"
    check(js(inside),'every control (incl. close) sits inside the panel at the current editor width')
    js("Object.assign(document.querySelector('.studio-dock').style,{flex:'0 0 440px',width:'440px'})");wait()   # 편집기를 좁힌다(오른쪽 배치는 flex 기준값이 폭)
    check(js(inside) and js("document.querySelector('.studio-find [name=next]').getBoundingClientRect().top>document.querySelector('.studio-find [name=search]').getBoundingClientRect().bottom"),'in a narrow editor the find tools move under the find field and nothing overflows')
    js("Object.assign(document.querySelector('.studio-dock').style,{flex:'',width:''})");wait()
    # 창 안에서 Ctrl+F = 다시 찾기만(바꾸기 줄 닫힘, 찾기 칸에 초점). 버튼(▸)으로도 여닫는다.
    page.keyboard.press('Control+f');wait()
    check(js("document.querySelector('.studio-find').dataset.mode")=='find' and not page.is_visible('.studio-find [name=replace]') and js("document.activeElement?.name")=='search','Ctrl+F inside the panel closes the replace row and focuses find')
    js("document.querySelector('.studio-find [name=mode]').click()");wait()
    check(js("document.querySelector('.studio-find').dataset.mode")=='replace' and js("document.activeElement?.name")=='replace' and js("document.querySelector('.studio-find [name=mode]').getAttribute('aria-expanded')")=='true','the toggle button opens the replace row')
    js("document.querySelector('.studio-find [name=mode]').click()");wait()
    check(js("document.querySelector('.studio-find').dataset.mode")=='find' and js("document.activeElement?.name")=='search','the toggle button closes it again')
    page.keyboard.press('Escape');wait()
    # 편집기에서 바로 Ctrl+H, 이어서 편집기로 돌아가 Ctrl+F를 누르면 바꾸기 줄이 닫힌다
    page.keyboard.press('Control+h');wait()
    check(js("document.querySelector('.studio-find').dataset.mode")=='replace','Ctrl+H from the editor opens replace mode')
    js("document.querySelector('.cm-content').focus()");page.keyboard.press('Control+f');wait()
    check(js("document.querySelector('.studio-find').dataset.mode")=='find' and js("document.activeElement?.name")=='search','Ctrl+F from the editor switches an open replace panel back to find only')
    page.keyboard.press('Control+f');wait()
    page.keyboard.press('Alt+r');wait()
    check(js("document.querySelector('.studio-find [name=re]').getAttribute('aria-pressed')")=='true','Alt+R toggles regexp in the search panel')
    page.keyboard.press('Alt+r')
    page.keyboard.press('Escape')
    js("document.getElementById('studioPaletteOpen').click()");wait()
    page.keyboard.type('@ma');wait()
    check(page.is_visible('.studio-palette') and 'main' in page.locator('.studio-palette-list button').first.inner_text(),'command palette @ lists functions of the pass')
    page.keyboard.press('Escape')
    js("document.getElementById('studioZoomIn').click()")
    check(js("getComputedStyle(document.querySelector('.cm-editor')).fontSize")=='13px','font size button reconfigures CodeMirror')
    js("document.getElementById('studioZoomOut').click()")
    box=js("""(()=>{const walker=document.createTreeWalker(document.querySelector('.cm-content'),NodeFilter.SHOW_TEXT);let node;
      while((node=walker.nextNode())){const i=node.textContent.indexOf('smoothstep');if(i>=0){const range=document.createRange();range.setStart(node,i+2);range.setEnd(node,i+3);const r=range.getBoundingClientRect();return [r.left+2,r.top+r.height/2];}}})()""")
    page.mouse.move(*box);wait(800)
    check('부드러운 계단' in (js("document.querySelector('.cm-tooltip-hover')?.textContent || ''")),'hovering a builtin shows its description')

    # ---- 예전 편집기 테스트에서 옮겨 온 기본 편집 동작 ----
    SRC2='#version 300 es\nprecision highp float;\nout vec4 fragColor;\nfloat wave(float x, float k) {\n    return sin(x * k);\n}\nvoid main() {\n    vec3 tint = vec3(1.0, 0.5, 0.0);\n    float a = 1;\n    float b = 2;\n    fragColor = vec4(tint * wave(a, 3.0), 1.0);\n}\n'
    def load(src):js("s=>testStudio.setProject({image:s,passes:[],imageChannels:{}})",src);wait(80)
    def place(a,b=None):js("a=>{const t=document.getElementById('studioCode');t.focus();t.setSelectionRange(a[0],a[1]);}",[a,a if b is None else b]);wait(40)
    def sel():return js("(t=>[t.selectionStart,t.selectionEnd])(document.getElementById('studioCode'))")
    load(SRC2)
    at=SRC2.index('float a = 1;')+len('float a = 1');place(at);page.keyboard.type('(')
    check(val()[at:at+2]=='()' and sel()==[at+1,at+1],'( auto-closes and keeps the caret inside')
    page.keyboard.type(')');check(val()[at:at+3]=='();' and sel()==[at+2,at+2],'typing ) steps over the auto-closed bracket')
    page.keyboard.press('Control+z');page.keyboard.press('Control+z');wait()
    load(SRC2);a=SRC2.index('float a');b=SRC2.index('float b = 2;')+5;place(a,b);page.keyboard.press('Tab')
    check('        float a = 1;\n        float b = 2;' in val(),'Tab indents every selected line')
    page.keyboard.press('Shift+Tab');check('    float a = 1;\n    float b = 2;' in val(),'Shift+Tab outdents them again')
    load(SRC2);at=SRC2.index('float a = 1;')+len('float a');place(at);page.keyboard.press('Tab')   # 4칸 들여쓴 줄의 11번째 칸 → 다음 탭 위치(12)까지
    check('\n    float a  = 1;' in val() and sel()==[at+1,at+1],'Tab with a single caret inserts spaces up to the next tab stop instead of indenting the line')
    load(SRC2);at=SRC2.index('float a = 1;');place(at,at+5);page.keyboard.press('Tab')   # 4번째 칸의 "float" → 다음 탭 위치(8)까지 공백
    check('\n         a = 1;' in val() and sel()==[at+4,at+4],'Tab over a selection inside one line replaces it with spaces')
    load(SRC2);place(SRC2.index('float a'));page.keyboard.press('Control+/');check('    // float a = 1;' in val(),'Ctrl+/ comments the line')   # 위 Tab 검사가 "float"를 공백으로 바꿨으므로 원본을 다시 넣는다
    page.keyboard.press('Control+/');check('    float a = 1;' in val() and '// float a' not in val(),'Ctrl+/ again uncomments it')
    page.keyboard.press('Alt+ArrowDown');check(val().index('float b = 2;')<val().index('float a = 1;'),'Alt+↓ moves the line down')
    page.keyboard.press('Alt+ArrowUp');page.keyboard.press('Control+Shift+KeyD');check(val().count('float a = 1;')==2,'Ctrl+Shift+D duplicates the line')
    load(SRC2);place(SRC2.index('float a'));page.keyboard.press('Control+l');check(js("(t=>t.value.slice(t.selectionStart,t.selectionEnd))(document.getElementById('studioCode'))").startswith('    float a = 1;'),'Ctrl+L selects the line')
    crumb=lambda:js("document.querySelector('#studioFunctions .studio-crumb-name').textContent")
    check(crumb()=='main()',f'the breadcrumb names the function around the caret: {crumb()}')
    place(SRC2.index('return sin'));check(crumb()=='wave()','moving the caret updates the breadcrumb')
    place(0);check(crumb()=='함수 2개',f'outside any function the breadcrumb counts the functions: {crumb()}')
    place(SRC2.index('float a'));js("document.getElementById('studioFunctions').click()");wait()
    rows=js("[...document.querySelectorAll('.studio-palette-list button')].map(b=>b.textContent)")
    check(page.is_visible('.studio-palette') and js("document.querySelector('.studio-palette-input').value")=='@','the breadcrumb opens the @ symbol palette')
    kinds=js("[...document.querySelectorAll('.studio-palette-list button')].map(b=>b.querySelector('.palette-kind')?.className||'')")
    check(rows[0].startswith('frag') and rows[1].startswith('wave') and rows[2].startswith('main') and 'is-output' in kinds[0] and 'is-function' in kinds[1] and 'is-function' in kinds[2],f'symbols are listed in document order with kind icons: {rows} {kinds}')
    check('main' in js("document.querySelector('.studio-palette-list .is-selected').textContent"),'the current function is preselected')
    page.keyboard.press('ArrowUp');wait()
    check(sel()==[SRC2.index('wave('),SRC2.index('wave(')+4],'moving through the list previews the symbol in the editor')
    page.keyboard.press('Escape');wait()
    check(sel()[0]==SRC2.index('float a') and not page.is_visible('.studio-palette'),'Escape closes the palette and restores the caret')
    js("document.getElementById('studioFunctions').click()");wait();page.keyboard.press('ArrowUp');page.keyboard.press('Enter');wait()
    check(sel()==[SRC2.index('wave('),SRC2.index('wave(')+4] and crumb()=='wave()','Enter jumps to the chosen function')

    # ---- GLSL 도우미 ----
    place(SRC2.index('3.0)')+1);wait(80)
    sig=js("(t=>t&&[t.textContent,t.querySelector('em')?.textContent])(document.querySelector('.cm-glsl-signature'))")
    check(sig and sig[1]=='float k','signature help highlights the argument being typed (wave → float k)')
    page.keyboard.press('Control+ArrowUp');check('wave(a, 3.1)' in val(),'Ctrl+↑ nudges the number by its last digit')
    page.keyboard.press('Shift+Control+ArrowDown');check('wave(a, 2.1)' in val(),'Shift+Ctrl+↓ nudges ten steps')
    sw=js("[...document.querySelectorAll('.cm-glsl-swatch')].map(n=>n.style.getPropertyValue('--swatch'))")
    check(sw==['rgb(255 128 0)'],f'a color swatch precedes 0..1 vec3 literals: {sw}')
    js("""()=>{const i=document.querySelector('.cm-glsl-color-input')||document.createElement('input');HTMLInputElement.prototype.showPicker=function(){};document.querySelector('.cm-glsl-swatch').click();const p=document.querySelector('.cm-glsl-color-input');p.value='#336699';p.dispatchEvent(new Event('input'));}""");wait()
    check('vec3(0.2, 0.4, 0.6)' in val(),'the swatch color picker writes 0..1 values')
    page.keyboard.press('Control+z');wait(80);check('vec3(1.0, 0.5, 0.0)' in val(),'Undo restores the color')
    check(js("document.querySelectorAll('.cm-indent-guides').length")>=3,'indent guide decorations are drawn')
    place(val().index('wave(a')+1);page.keyboard.press('F12');wait()
    check(sel()==[SRC2.index('wave('),SRC2.index('wave(')+4],'F12 jumps to the function definition')
    box=js("""(()=>{const w=document.createTreeWalker(document.querySelector('.cm-content'),NodeFilter.SHOW_TEXT);let n;while((n=w.nextNode())){const i=n.textContent.indexOf('tint *');if(i>=0){const r=document.createRange();r.setStart(n,i+1);r.setEnd(n,i+2);const c=r.getBoundingClientRect();return [c.left+1,c.top+c.height/2];}}})()""")
    page.keyboard.down('Control');page.mouse.click(*box);page.keyboard.up('Control');wait()
    check(sel()==[SRC2.index('tint ='),SRC2.index('tint =')+4],'Ctrl+click jumps to the variable declaration')
    page.keyboard.press('F2');wait(120);check(js("document.getElementById('studioPromptDialog').open"),'F2 opens the rename dialog')
    js("(i=>{i.value='color';})(document.getElementById('studioDialogInput'))");page.keyboard.press('Enter');wait(120)
    check(val().count('color')==2 and 'tint' not in val(),'rename replaces every use of the name')
    page.keyboard.press('Control+z');wait(80)
    nb=js("""(()=>{const line=[...document.querySelectorAll('.cm-line')].find(l=>l.textContent.includes('float b = 2;'));const num=[...line.querySelectorAll('span')].find(x=>x.textContent==='2');const c=num.getBoundingClientRect();return [c.left+c.width/2,c.top+c.height/2];})()""")
    page.keyboard.down('Alt');page.mouse.move(*nb);page.mouse.down();page.mouse.move(nb[0]+20,nb[1],steps=4);page.mouse.up();page.keyboard.up('Alt');wait()
    check('float b = 7;' in val(),'Alt+drag on a number scrubs its value')
    load(SRC2);caret_to_end();page.keyboard.type('SYNTAX');js("testStudio.apply()");wait(150)
    lens=js("[...document.querySelectorAll('.cm-error-lens')].map(n=>n.className+'|'+n.textContent)")
    check(lens and 'test diagnostic' in lens[0] and 'is-stale' not in lens[0],f'the compile error message is shown at the end of its line: {lens}')
    page.keyboard.type(' ');wait()
    check(js("document.querySelectorAll('.cm-error-lens.is-stale').length")==1,'editing marks the error message as stale until the next compile')
    js("document.getElementById('studioLintPanel').click()");wait();check(page.is_visible('.cm-panel-lint'),'the error list panel opens from the menu')
    page.keyboard.press('Escape');load(SRC2)
    js("document.getElementById('studioFoldAll').click()");wait();check(js("document.querySelectorAll('.cm-foldPlaceholder').length")==2,'fold all collapses both functions')
    js("document.getElementById('studioUnfoldAll').click()");wait();check(js("document.querySelectorAll('.cm-foldPlaceholder').length")==0,'unfold all expands them')
    place(SRC2.index('float a'));page.keyboard.press('Control+Alt+ArrowDown');check('다중 선택 2개' in page.locator('#studioCursor').inner_text(),'Ctrl+Alt+↓ adds a cursor on the next line')
    page.keyboard.press('Escape')
    page.keyboard.press('Control+h');wait()
    check(page.is_visible('.cm-search') and js("document.activeElement?.name")=='replace' and page.is_visible('.studio-find [name=replaceAll]'),'Ctrl+H opens search with the replace row shown and focused')
    check('찾기' in js("document.querySelector('.cm-search input[name=search]').placeholder") and '모두 바꾸기' in js("document.querySelector('.cm-search').textContent"),'search panel labels are Korean (EditorState.phrases)')
    page.keyboard.press('Escape')
    # ---- 화면 전환 상태 유지: 패스별 접힘 · 탭 줄 · 집중 모드 ----
    js('''src => testStudio.setProject({image:src,passes:["A","B","C"].map(name=>({name,fragment:src,format:"rgba8",scale:1,channels:{}})),imageChannels:{}})''',SRC2);wait()
    tab=lambda name:js(f"[...document.querySelectorAll('#studioPassTabs button')].find(b=>b.textContent==='{name}').click()") or wait()
    check(js('''() => {const box=document.getElementById('studioPassTabs').getBoundingClientRect();
      return [...document.querySelectorAll('#studioPassTabs button')].every(b=>{const r=b.getBoundingClientRect();return r.width>0&&r.left>=box.left-1&&r.right<=box.right+1;});}'''),'with three buffers in the side layout every pass tab is fully visible')
    js("document.getElementById('studioFoldAll').click()");wait();tab('Buffer A');check(js("document.querySelectorAll('.cm-foldPlaceholder').length")==0,'another pass starts unfolded')
    tab('Image');check(js("document.querySelectorAll('.cm-foldPlaceholder').length")==2,'returning to a pass restores its folded blocks')
    js("document.getElementById('studioUnfoldAll').click()");wait()
    js("document.getElementById('studioMaximize').click()");wait()
    check(js("Math.abs(document.getElementById('studioDock').getBoundingClientRect().width-document.getElementById('stage').getBoundingClientRect().width)<2"),'focus mode in the side layout gives the editor the full stage width')
    js("document.getElementById('studioMaximize').click()");wait()
    check(js("document.getElementById('studioDock').getBoundingClientRect().width<document.getElementById('stage').getBoundingClientRect().width*0.8"),'leaving focus mode restores the side-by-side width')
    # ---- Enter 들여쓰기: 소괄호도 중괄호처럼 열리고, 괄호 안에서 손으로 맞춘 들여쓰기는 다음 줄에 유지 ----
    js("s=>{document.getElementById('studioCode').value=s}","void main() {\n    vec3 c = mix");wait();caret_to_end()
    page.keyboard.type("(");page.keyboard.press('Enter');wait()
    check(val()=="void main() {\n    vec3 c = mix(\n        \n    )",'Enter between ( ) opens an indented line like braces')
    page.keyboard.type("a,");page.keyboard.press('Enter');page.keyboard.press('Tab');page.keyboard.type("b,");page.keyboard.press('Enter');page.keyboard.type("c");wait()
    check(val()=="void main() {\n    vec3 c = mix(\n        a,\n            b,\n            c\n    )",'inside parentheses Enter keeps the indentation of the line above (incl. a manual Tab)')
    js('''src => testStudio.setProject({image:src,passes:[],imageChannels:{}})''',SRC2);wait()
    js("document.getElementById('studioCode').value=''");wait()
    check('GLSL 코드를 입력하세요' in js("document.querySelector('.cm-placeholder')?.textContent || ''"),'an empty document shows a placeholder hint')
    check(errors==[],f'no Chromium page exceptions: {errors}')
    print(f'PASS all {n[0]} editor checks')
    browser.close()
